"OLAYLAR_ORTACAG_YER_SONRASI:1122-01-01:0":{"b": ["Konkordat wormacki: koniec sporu o inwestyturę", "4b2cf229"], "d": ["Konkordat wormacki z 1122 roku zakończył spór o inwestyturę trwający od czasów Grzegorza VII.", "5a532208"]},
"OLAYLAR_ORTACAG_YER_SONRASI:1135-01-01:0":{"b": ["Flota Pizy złupiła Amalfi", "357149dc"], "d": ["W kampanii 1135 roku (oraz 1136-37) Pizańczycy, przybywszy z pomocą Robertowi, księciu Kapui, w Neapolu przeciwko królowi Sycylii Rogerowi II, zniszczyli Amalfi i złupili wyspę Ischia.", "e362cfdf"]}
